AssistantMessageToolRequest(name='create', tool_call_id='tooluse_tUrdzCoIUwq7opRS8HdnIm', arguments={'file_text': 'const ANSWERS = {
  q1: ['java', 'c'],
  q2: ['rust', 'c++'],
  q3: ['haskell', 'javascript', 'python'],
};

const QUESTION_LABELS = {
  q1: 'Which are statically typed languages?',
  q2: 'Which are primarily used for systems programming?',
  q3: 'Which languages support first-class functions?',
};

const form = document.getElementById('quiz-form');
const submitBtn = document.getElementById('submit-btn');
const resultsSection = document.getElementById('results');
const resultsContent = document.getElementById('results-content');
const retryBtn = document.getElementById('retry-btn');

function getSelected(name) {
  return [...form.querySelectorAll(`input[name="${name}"]:checked`)].map(el => el.value);
}

function arraysEqual(a, b) {
  return a.length === b.length && [...a].sort().every((v, i) => v === [...b].sort()[i]);
}

function applyResultStyles() {
  Object.entries(ANSWERS).forEach(([name, correct]) => {
    const selected = getSelected(name);
    const choices = form.querySelectorAll(`input[name="${name}"]`);

    choices.forEach(input => {
      const label = input.closest('.choice');
      const val = input.value;
      const isCorrect = correct.includes(val);
      const isSelected = selected.includes(val);

      label.classList.add('disabled');

      if (isSelected && isCorrect) {
        label.classList.add('correct');
      } else if (isSelected && !isCorrect) {
        label.classList.add('incorrect');
      } else if (!isSelected && isCorrect) {
        label.classList.add('missed');
      }
    });
  });
}

function buildResults() {
  const breakdown = document.createElement('ul');
  breakdown.className = 'result-breakdown';
  breakdown.setAttribute('aria-label', 'Question breakdown');

  let score = 0;

  Object.entries(ANSWERS).forEach(([name, correct]) => {
    const selected = getSelected(name);
    const pass = arraysEqual(selected, correct);
    if (pass) score++;

    const li = document.createElement('li');
    li.className = pass ? 'pass' : 'fail';
    li.textContent = `${pass ? '✓' : '✗'} ${QUESTION_LABELS[name]}`;
    breakdown.appendChild(li);
  });

  const total = Object.keys(ANSWERS).length;
  const pct = Math.round((score / total) * 100);

  resultsContent.innerHTML = `
    <div class="score-display" aria-label="${score} out of ${total} correct">${score} / ${total}</div>
    <p class="score-label">${pct}% — ${scoreMessage(pct)}</p>
  `;
  resultsContent.appendChild(breakdown);
}

function scoreMessage(pct) {
  if (pct === 100) return 'Perfect score! 🎉';
  if (pct >= 67)  return 'Good job!';
  if (pct >= 34)  return 'Keep studying!';
  return 'Better luck next time.';
}

form.addEventListener('submit', e => {
  e.preventDefault();
  applyResultStyles();
  buildResults();
  submitBtn.disabled = true;
  resultsSection.hidden = false;
  resultsSection.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
});

retryBtn.addEventListener('click', () => {
  form.reset();

  // Remove result classes from all choices
  form.querySelectorAll('.choice').forEach(label => {
    label.classList.remove('correct', 'incorrect', 'missed', 'disabled');
  });

  submitBtn.disabled = false;
  resultsSection.hidden = true;
  resultsContent.innerHTML = '';
  form.querySelector('.choice').focus();
});
