const form = document.getElementById('quiz-form');
const submitBtn = document.getElementById('submit-btn');
const resultsSection = document.getElementById('results');
const resultsContent = document.getElementById('results-content');
const retryBtn = document.getElementById('retry-btn');

function getSelected(name) {
  return [...form.querySelectorAll(`input[name="${name}"]:checked`)].map(el => el.value);
}

function arraysEqual(a, b) {
  return a.length === b.length && [...a].sort().every((v, i) => v === [...b].sort()[i]);
}

function applyResultStyles() {
  Object.entries(ANSWERS).forEach(([name, correct]) => {
    const selected = getSelected(name);
    const choices = form.querySelectorAll(`input[name="${name}"]`);

    choices.forEach(input => {
      const label = input.closest('.choice');
      const val = input.value;
      const isCorrect = correct.includes(val);
      const isSelected = selected.includes(val);

      label.classList.add('disabled');

      if (isSelected && isCorrect) {
        label.classList.add('correct');
      } else if (isSelected && !isCorrect) {
        label.classList.add('incorrect');
      } else if (!isSelected && isCorrect) {
        label.classList.add('missed');
      }
    });
  });
}

